-- v65: the bytes a feedback document points at.
--
-- **The row is the metadata; the object is the bytes.** The object key is generated by M18 and
-- never derived from the receipt, so a receipt cannot be turned into a bucket address. A
-- withdrawal deletes every object first and the feedback row second; these rows go with it via
-- the cascade, because a attachment without its feedback is not addressable by anything.
--
-- **No count in a CHECK.** Five attachments per feedback is a product limit, not a data integrity
-- invariant: changing the limit must not require a migration. `position` and `size_bytes` are the
-- two facts the storage layer would otherwise have to infer.
CREATE TABLE feedback_attachment (
  id          TEXT PRIMARY KEY,
  feedback_id TEXT NOT NULL REFERENCES user_feedback(id) ON DELETE CASCADE,
  position    INTEGER NOT NULL,
  filename    TEXT NOT NULL,
  media_type  TEXT NOT NULL,
  size_bytes  BIGINT NOT NULL,
  sha256      TEXT NOT NULL,
  object_key  TEXT NOT NULL UNIQUE,
  created_at  TEXT NOT NULL,
  UNIQUE (feedback_id, position),
  CHECK (position >= 0),
  CHECK (size_bytes > 0)
);

CREATE INDEX idx_feedback_attachment_feedback ON feedback_attachment(feedback_id);

COMMENT ON TABLE feedback_attachment IS
  'One image or short video attached to a feedback document (v65). Bytes live in the private bucket; this table is the metadata and the object key.';
COMMENT ON COLUMN feedback_attachment.id IS
  'ULID. Also part of the object key, so the key is opaque and cannot be derived from the receipt.';
COMMENT ON COLUMN feedback_attachment.feedback_id IS
  'The feedback this attachment belongs to. Deleting the feedback deletes these rows.';
COMMENT ON COLUMN feedback_attachment.position IS
  'Zero-based order the attachments were submitted in; the archive document keeps it.';
COMMENT ON COLUMN feedback_attachment.filename IS
  'The basename the client sent, after control characters are removed and the length is capped. Display only: it never becomes a path or an object key.';
COMMENT ON COLUMN feedback_attachment.media_type IS
  'The canonical type the server detected from the file header, never the client-declared one.';
COMMENT ON COLUMN feedback_attachment.size_bytes IS
  'The stored byte count, greater than zero.';
COMMENT ON COLUMN feedback_attachment.sha256 IS
  'Lowercase SHA-256 of the stored bytes, computed by the server. The client may show its own digest in the preview; this one is the record.';
COMMENT ON COLUMN feedback_attachment.object_key IS
  'feedback/attachments/YYYY/MM/DD/<ULID>.<ext> in the private bucket. No original filename and no receipt, by design.';
COMMENT ON COLUMN feedback_attachment.created_at IS
  'RFC3339 UTC.';
